"python3 - <<'PY'
import json, urllib.request, urllib.parse
urls=['https://www.gamechest.gg/products.json?limit=250','https://www.gamechest.gg/collections/all/products.json?limit=250']
for url in urls:
    print('\nURL',url)
    with urllib.request.urlopen(url, timeout=20) as r:
        data=json.load(r)
    products=data.get('products',[])
    print('count',len(products))
    for p in products:
        text=' '.join(str(p.get(k,'')) for k in ['title','handle','vendor','product_type'] + []) + ' ' + ' '.join(p.get('tags',[]))
        if any(term.lower() in text.lower() for term in ['zelda','breath','wild','legend']):
            print(json.dumps({k:p.get(k) for k in ['title','handle','vendor','product_type','tags']}, ensure_ascii=False))
            print('url','https://www.gamechest.gg/products/'+p.get('handle',''))
# predictive terms
for q in ['zelda','breath of the wild','legend of zelda','botw']:
    url='https://www.gamechest.gg/search/suggest.json?'+urllib.parse.urlencode({'q':q,'resources[type]':'product','resources[limit]':'10'})
    print('\nSUGGEST',q)
